// "GlyphLessFont": a 573-byte TrueType font whose only real glyph is empty,
// used for the invisible text layer of searchable PDFs so any Unicode text
// can be placed without embedding a real font.
//
// Bytes copied from Tesseract OCR, src/api/pdf_ttf.h (pdf.ttf)
// https://github.com/tesseract-ocr/tesseract
// Copyright 2011–2020 Google Inc. Licensed under the Apache License, Version 2.0
// (http://www.apache.org/licenses/LICENSE-2.0).

const GLYPHLESS_TTF_BASE64 =
  '';

export function glyphlessFont(): Uint8Array {
  const bin = atob(GLYPHLESS_TTF_BASE64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
